def migrar_equipos(apps, schema_editor):
    Equipo = apps.get_model("deportes", "Equipo")
    Facultad = apps.get_model("deportes", "Facultad")
    database = schema_editor.connection.alias

    for equipo in Equipo.objects.using(database).all().iterator():
        nombre = " ".join((equipo.facultad or "").split()).upper()
        if not nombre:
            nombre = "SIN ASIGNAR"

        facultad = Facultad.objects.using(database).filter(nombre=nombre).first()
        if facultad is None:
            sigla_base = "".join(palabra[0] for palabra in nombre.split())[:16] or "FAC"
            sigla = sigla_base
            sufijo = 1
            while Facultad.objects.using(database).filter(sigla=sigla).exists():
                sufijo_texto = str(sufijo)
                sigla = f"{sigla_base[:20 - len(sufijo_texto)]}{sufijo_texto}"
                sufijo += 1
            facultad = Facultad.objects.using(database).create(
                nombre=nombre,
                sigla=sigla,
            )

        equipo.facultad_nueva_id = facultad.pk
        equipo.color_nuevo = equipo.color_principal or "#000000"
        equipo.estado_nuevo = "ACTIVO" if equipo.activo else "INACTIVO"
        equipo.creado_en_nuevo = equipo.inscrito_en or django.utils.timezone.now()
        equipo.save(
            update_fields=[
                "facultad_nueva",
                "color_nuevo",
                "estado_nuevo",
                "creado_en_nuevo",
            ],
            using=database,
        )


